#define NEOCC_TOKEN_BLOCK_SIZE (256 * 1024)

/* Separate malloc storage permits max_align_t alignment without imposing
 * stricter alignment on the NEOioic object's own member block.
 */
struct neocc_token_block {
	struct neocc_token_block *next;
	size_t capacity;
	size_t used;
	size_t live;
	max_align_t data[];
};

union token_header {
	struct {
		size_t size;
		size_t capacity;
		int live;
	} allocation;
	max_align_t alignment;
};

static void blocks_clear(struct neocc_token_block **head)
{
	while (*head) {
		struct neocc_token_block *block = *head;

		*head = block->next;
		free(block);
	}
}

static void tokens_clear(struct em_tokens *members)
{
	while (members->inline_head) {
		struct neocc_inline *entry = members->inline_head;

		members->inline_head = entry->next;
		free(entry);
	}
	/* Inline body buffers are part of streams, released below. */
	blocks_clear(&members->symbols);
	blocks_clear(&members->streams);
	free(members->table);
	memset(members, 0, sizeof(*members));
}

static void *block_allocate(struct neocc_token_block **head, size_t size)
{
	struct neocc_token_block *block;
	union token_header *header;
	size_t alignment = _Alignof(max_align_t);
	size_t padded, required, capacity;

	if (size > SIZE_MAX - alignment + 1)
		return NULL;
	padded = (size + alignment - 1) / alignment * alignment;
	if (padded > SIZE_MAX - sizeof(*header))
		return NULL;
	required = padded + sizeof(*header);
	for (block = *head; block; block = block->next)
		if (required <= block->capacity - block->used)
			break;
	if (!block) {
		capacity = required > NEOCC_TOKEN_BLOCK_SIZE ? required :
			NEOCC_TOKEN_BLOCK_SIZE;
		if (capacity > SIZE_MAX - sizeof(*block))
			return NULL;
		block = malloc(sizeof(*block) + capacity);
		if (!block)
			return NULL;
		*block = (struct neocc_token_block){ *head, capacity, 0, 0 };
		*head = block;
	}
	header = (union token_header *)((unsigned char *)block->data +
					block->used);
	header->allocation.size = size;
	header->allocation.capacity = padded;
	header->allocation.live = 1;
	block->used += required;
	block->live++;
	return header + 1;
}

static union token_header *block_find(struct neocc_token_block *head,
	void *pointer, struct neocc_token_block **owner)
{
	uintptr_t address = (uintptr_t)pointer;

	for (; head; head = head->next) {
		uintptr_t first = (uintptr_t)head->data;
		size_t offset;
		union token_header *header;

		if (address < first || address - first < sizeof(*header) ||
		    address - first >= head->used)
			continue;
		offset = address - first - sizeof(*header);
		if (offset % _Alignof(max_align_t))
			return NULL;
		header = (union token_header *)((unsigned char *)head->data +
					      offset);
		if (!header->allocation.live)
			return NULL;
		*owner = head;
		return header;
	}
	return NULL;
}

static void block_release(struct neocc_token_block **head,
	struct neocc_token_block *block, union token_header *header)
{
	struct neocc_token_block **link;

	header->allocation.live = 0;
	if (--block->live) {
		if ((unsigned char *)(header + 1) +
		    header->allocation.capacity ==
		    (unsigned char *)block->data + block->used)
			block->used = (unsigned char *)header -
				(unsigned char *)block->data;
		return;
	}
	if (block->capacity <= NEOCC_TOKEN_BLOCK_SIZE) {
		block->used = 0;
		return;
	}
	for (link = head; *link != block; link = &(*link)->next)
		;
	*link = block->next;
	free(block);
}

static int stream_resize(struct em_tokens *members,
	const struct neocc_token_resize *request, void **output)
{
	struct neocc_token_block *block = NULL;
	union token_header *header = NULL;
	void *pointer;
	size_t old_size;

	*output = NULL;
	if (request->pointer) {
		header = block_find(members->streams, request->pointer, &block);
		if (!header)
			return RN_INVALIDARG;
	}
	if (!request->size) {
		if (header)
			block_release(&members->streams, block, header);
		return R_P;
	}
	old_size = header ? header->allocation.size : 0;
	if (header && request->size <= header->allocation.capacity) {
		header->allocation.size = request->size;
		*output = request->pointer;
		return R_P;
	}
	/* Keep the original allocator's tail-growth behavior. Do not rewind the
	 * old allocation before a fallible allocation: failure preserves it.
	 */
	if (header && request->size <= SIZE_MAX - _Alignof(max_align_t) + 1) {
		size_t alignment = _Alignof(max_align_t);
		size_t padded = (request->size + alignment - 1) /
			alignment * alignment;
		size_t extra = padded - header->allocation.capacity;

		if ((unsigned char *)request->pointer +
		    header->allocation.capacity ==
		    (unsigned char *)block->data + block->used &&
		    extra <= block->capacity - block->used) {
			block->used += extra;
			header->allocation.size = request->size;
			header->allocation.capacity = padded;
			*output = request->pointer;
			return R_P;
		}
	}
	pointer = block_allocate(&members->streams, request->size);
	if (!pointer)
		return R_N;
	if (header) {
		memcpy(pointer, request->pointer, old_size);
		block_release(&members->streams, block, header);
	}
	*output = pointer;
	return R_P;
}

static int inline_reset(struct em_tokens *members)
{
	while (members->inline_head) {
		struct neocc_inline *entry = members->inline_head;
		struct neocc_token_resize request = { entry->body.str, 0 };
		void *unused;
		int result = stream_resize(members, &request, &unused);

		if (!RP(result))
			return result;
		members->inline_head = entry->next;
		free(entry);
	}
	members->inline_tail = NULL;
	return R_P;
}

static int inline_save(struct em_tokens *members,
	const struct neocc_inline_save *request, struct neocc_inline **output)
{
	struct neocc_inline *entry;
	size_t length;

	if (!request->symbol || !request->filename)
		return RN_INVALIDARG;
	length = strlen(request->filename);
	if (length > SIZE_MAX - sizeof(*entry) - 1)
		return RN_INVALIDARG;
	entry = malloc(sizeof(*entry) + length + 1);
	if (!entry)
		return R_N;
	*entry = (struct neocc_inline){ .symbol = request->symbol,
		.body.last_line_num = -1 };
	memcpy(entry->filename, request->filename, length + 1);
	if (members->inline_tail)
		members->inline_tail->next = entry;
	else
		members->inline_head = entry;
	members->inline_tail = entry;
	*output = entry;
	return R_P;
}

static int token_intern(struct em_tokens *members,
	const struct neocc_token_intern *request, struct neocc_token_result *out)
{
	struct neocc_token *token, **link, **table;
	size_t i, capacity;
	unsigned int hash = 1;

	if (!request->text || request->length > INT_MAX ||
	    request->length > SIZE_MAX - sizeof(*token) - 1)
		return RN_INVALIDARG;
	for (i = 0; i < request->length; i++)
		hash += (hash << 5) + (hash >> 27) +
			(unsigned char)request->text[i];
	link = &members->hash[hash & (NEOCC_TOKEN_HASH_SIZE - 1)];
	while ((token = *link)) {
		if ((size_t)token->len == request->length &&
		    !memcmp(token->str, request->text, request->length)) {
			*out = (struct neocc_token_result){ token,
				NEOCC_TOKEN_FIRST + (int)members->count };
			return R_P;
		}
		link = &token->hash_next;
	}
	if (members->count >= NEOCC_TOKEN_LIMIT - NEOCC_TOKEN_FIRST)
		return R_N;
	if (members->count == members->capacity) {
		capacity = members->capacity ? members->capacity * 2 : 512;
		if (capacity > SIZE_MAX / sizeof(*table))
			return R_N;
		table = realloc(members->table, capacity * sizeof(*table));
		if (!table)
			return R_N;
		members->table = table;
		members->capacity = capacity;
	}
	token = block_allocate(&members->symbols,
			       sizeof(*token) + request->length + 1);
	if (!token)
		return R_N;
	memset(token, 0, sizeof(*token));
	token->tok = NEOCC_TOKEN_FIRST + (int)members->count;
	token->len = (int)request->length;
	memcpy(token->str, request->text, request->length);
	token->str[request->length] = 0;
	members->table[members->count++] = token;
	*link = token;
	*out = (struct neocc_token_result){ token,
		NEOCC_TOKEN_FIRST + (int)members->count };
	return R_P;
}

static int tokens_open(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_OPEN_;
	return R_P;
}

static int tokens_close(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_CLOSE_;
	if (!self->ref_count)
		tokens_clear(self->members);
	return R_P;
}

static int tokens_interact0(struct object *self, unsigned int action,
	const struct vr *caller_context)
{
	if (action != NEOCC_AC0_TOKENS_RESET &&
	    action != NEOCC_AC0_TOKENS_RESET_INLINES) {
		SBO_OBJECT_INTERACT0;
	}
	if (!self->ref_count)
		return RN_INVALIDARG;
	if (action == NEOCC_AC0_TOKENS_RESET_INLINES)
		return inline_reset(self->members);
	tokens_clear(self->members);
	return R_P;
}

static int tokens_interact3(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_tokens *members = self->members;
	struct neocc_token_result result = { NULL,
		NEOCC_TOKEN_FIRST + (int)members->count };
	int status;

	if (action != NEOCC_AC3_TOKENS_INTERN &&
	    action != NEOCC_AC3_TOKENS_QUERY &&
	    action != NEOCC_AC3_TOKENS_RESIZE &&
	    action != NEOCC_AC3_TOKENS_SAVE_INLINE) {
		SBO_OBJECT_INTERACT3;
	}
	if (output_quantity)
		*output_quantity = 0;
	if (!self->ref_count || !input_stream || !output_stream ||
	    !output_quantity)
		return RN_INVALIDARG;
	if (action == NEOCC_AC3_TOKENS_SAVE_INLINE) {
		struct neocc_inline_save request;
		struct neocc_inline *entry;

		if (quantity != sizeof(request) || capacity < sizeof(entry))
			return RN_INVALIDARG;
		memcpy(&request, input_stream, sizeof(request));
		status = inline_save(members, &request, &entry);
		if (!RP(status))
			return status;
		memcpy(output_stream, &entry, sizeof(entry));
		*output_quantity = sizeof(entry);
		return R_P;
	}
	if (action == NEOCC_AC3_TOKENS_RESIZE) {
		struct neocc_token_resize request;
		void *pointer;

		if (quantity != sizeof(request) || capacity < sizeof(pointer))
			return RN_INVALIDARG;
		memcpy(&request, input_stream, sizeof(request));
		status = stream_resize(members, &request, &pointer);
		if (!RP(status))
			return status;
		memcpy(output_stream, &pointer, sizeof(pointer));
		*output_quantity = sizeof(pointer);
		return R_P;
	}
	if (capacity < sizeof(result))
		return RN_INVALIDARG;
	if (action == NEOCC_AC3_TOKENS_QUERY) {
		int id;

		if (quantity != sizeof(id))
			return RN_INVALIDARG;
		memcpy(&id, input_stream, sizeof(id));
		if (id >= NEOCC_TOKEN_FIRST && id < result.next)
			result.token = members->table[id - NEOCC_TOKEN_FIRST];
		status = result.token || id == NEOCC_TOKEN_FIRST - 1 ?
			R_P : RO_VAINLY;
	} else {
		struct neocc_token_intern request;

		if (quantity != sizeof(request))
			return RN_INVALIDARG;
		memcpy(&request, input_stream, sizeof(request));
		status = token_intern(members, &request, &result);
		if (!RP(status))
			return status;
	}
	memcpy(output_stream, &result, sizeof(result));
	*output_quantity = sizeof(result);
	return status;
}

static int tokens_input(struct object *self, unsigned char *input_stream,
	unsigned int quantity, const struct vr *caller_context)
{
	SBO_OBJECT_INPUT;
}

static int tokens_output(struct object *self, unsigned char *output_stream,
	unsigned int capacity, unsigned int *output_quantity,
	const struct vr *caller_context)
{
	SBO_OBJECT_OUTPUT;
}

static int tokens_io_put(struct object *self, unsigned char *input_stream,
	unsigned int quantity, unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	SBO_OBJECT_IOPUT;
}

static int tokens_interact1(struct object *self, unsigned int action,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_tokens *members = self->members;
	struct neocc_inline *entry = members->inline_head;

	*output_quantity = 0;
	if (action != NEOCC_AC1_TOKENS_FIRST_INLINE) {
		SBO_OBJECT_INTERACT1;
	}
	if (!self->ref_count || capacity < sizeof(entry))
		return RN_INVALIDARG;
	memcpy(output_stream, &entry, sizeof(entry));
	*output_quantity = sizeof(entry);
	return R_P;
}

static int tokens_interact2(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	const struct vr *caller_context)
{
	SBO_OBJECT_INTERACT2;
}

void tog_tokens(struct object *object)
{
	object->open = tokens_open;
	object->input = tokens_input;
	object->output = tokens_output;
	object->io_put = tokens_io_put;
	object->interact0 = tokens_interact0;
	object->interact1 = tokens_interact1;
	object->interact2 = tokens_interact2;
	object->interact3 = tokens_interact3;
	object->close = tokens_close;
}
